/* DemandTrajectoryCard — demand trajectory insight card for the chatbot.
 *
 * Renders from the backend's structured Laya payload (card type
 * "demand_trajectory"): medicine, analysis_date, trajectory and the exact
 * supporting metrics. Nothing here is generated by an LLM, no metric is
 * invented, and an invalid/missing payload renders an explicit
 * unavailable state instead of substituted values from another state.
 *
 * Standalone on purpose: no dependencies on app.js, so it can be loaded
 * before app.js and unit-tested under Node (module.exports).
 */
"use strict";

const DTC_TRAJECTORIES = {
  spiking: {
    label: "Spiking", tone: "spike",
    icon: `<svg viewBox="0 0 24 24" width="16" height="16" aria-hidden="true"><path d="M3 17l6-6 4 4 8-8" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/><path d="M15 7h6v6" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/></svg>`,
  },
  rising: {
    label: "Rising", tone: "rise",
    icon: `<svg viewBox="0 0 24 24" width="16" height="16" aria-hidden="true"><path d="M3 17l6-6 4 4 8-8" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/><path d="M15 7h6v6" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/></svg>`,
  },
  stable: {
    label: "Stable", tone: "stable",
    icon: `<svg viewBox="0 0 24 24" width="16" height="16" aria-hidden="true"><path d="M3 12h15" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"/><path d="M14 7l5 5-5 5" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/></svg>`,
  },
  falling: {
    label: "Falling", tone: "fall",
    icon: `<svg viewBox="0 0 24 24" width="16" height="16" aria-hidden="true"><path d="M3 7l6 6 4-4 8 8" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/><path d="M15 17h6v-6" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/></svg>`,
  },
};

const DTC_NEGLIGIBLE_PCT = 2; // |change| below this counts as "in line"
const DTC_DISCLAIMER =
  "This is a model prediction based on historical sales data. It does not " +
  "establish the cause of the increase or independently prove that demand " +
  "will remain high.";

/* Same escaping as app.js's esc(); inlined so the component is standalone. */
const dtcEsc = (v) => String(v ?? "").replace(/[&<>"']/g, (c) => ({
  "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));

/* Strict numeric validation: only finite numbers count, anything else is
 * "unavailable" — never coerced, never defaulted to 0. */
const dtcNum = (v) => (typeof v === "number" && Number.isFinite(v) ? v : null);

/* Display helper: up to 2 decimals, trailing zeros trimmed (5.57, 4.5). */
const dtcFmt = (v) => String(Math.round(v * 100) / 100);

/* Percent change recent vs baseline — deterministic, null when it cannot be
 * computed honestly (missing/NaN metric or non-positive baseline). */
function dtcBaselinePct(recent, baseline) {
  if (!Number.isFinite(recent) || !Number.isFinite(baseline) || baseline <= 0) {
    return null;
  }
  return ((recent - baseline) / baseline) * 100;
}

/* Operational interpretation from trajectory + metrics. States facts and
 * operational posture only: no invented causes, no promises about future
 * demand, no weather claims. */
function dtcMeaning(trajectory, pct) {
  if (pct === null) {
    return `Laya classifies this product's demand as ${trajectory}, but the ` +
      "supplied demand metrics for this state don't allow a baseline " +
      "comparison, so none is shown.";
  }
  const rounded = Math.round(pct);
  if (pct > DTC_NEGLIGIBLE_PCT) {
    return `Demand is running about ${Math.abs(rounded)}% above its historical ` +
      "baseline, which supports monitoring for a potential demand increase. " +
      `Laya classifies the trajectory as ${trajectory}.`;
  }
  if (pct < -DTC_NEGLIGIBLE_PCT) {
    return `Demand is running about ${Math.abs(rounded)}% below its historical ` +
      "baseline, which supports reviewing current stock coverage. " +
      `Laya classifies the trajectory as ${trajectory}.`;
  }
  return `Demand is in line with its historical baseline (within ` +
    `${DTC_NEGLIGIBLE_PCT}%), so there is no notable deviation to act on. ` +
    `Laya classifies the trajectory as ${trajectory}.`;
}

/* Explicit unavailable state: shown when the payload itself is unusable.
 * Deliberately displays no numbers — nothing is substituted. */
function dtcInvalidCard() {
  return `<div class="dtc dtc--invalid" role="note">
    <div class="dtc-head">
      <span class="dtc-ico dtc-ico--none" aria-hidden="true"><svg viewBox="0 0 24 24" width="16" height="16"><path d="M12 3a9 9 0 100 18 9 9 0 000-18zm0 4v6m0 3.5v.1" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg></span>
      <div class="dtc-head-main">
        <div class="dtc-title">Demand trajectory</div>
        <div class="dtc-date">Prediction unavailable</div>
      </div>
    </div>
    <div class="dtc-sec">
      <p class="dtc-p dtc-muted">This prediction can't be displayed because the
      structured payload is missing or invalid. No values are substituted from
      another historical state.</p>
    </div>
  </div>`;
}

/* Main component: validated structured payload -> HTML string. */
function DemandTrajectoryCard(c) {
  const data = (c && typeof c === "object") ? c : null;
  const medicine = (data && typeof data.medicine === "string")
    ? data.medicine.trim() : "";
  const trajKey = (data && typeof data.trajectory === "string")
    ? data.trajectory.toLowerCase() : "";
  /* own-property check: inherited keys like "constructor" must not pass. */
  const meta = Object.prototype.hasOwnProperty.call(DTC_TRAJECTORIES, trajKey)
    ? DTC_TRAJECTORIES[trajKey] : null;
  if (!medicine || !meta) return dtcInvalidCard();   // never fabricate a title/classification

  const analysisDate = (data && typeof data.analysis_date === "string")
    ? data.analysis_date.trim() : "";
  const recent = dtcNum(data.recent_daily_demand);
  const baseline = dtcNum(data.baseline_daily_demand);
  const pct = dtcBaselinePct(recent, baseline);

  // Section 3: label/value rows — aligned, explicit when a metric is absent.
  const recentRow = recent === null
    ? `<span class="dtc-na">Unavailable</span>`
    : `${dtcFmt(recent)} units/day`;
  const baselineRow = baseline === null
    ? `<span class="dtc-na">Unavailable</span>`
    : `${dtcFmt(baseline)} units/day`;
  let cmpLabel = "Baseline comparison";
  let cmpValue = `<span class="dtc-na">Unavailable</span>`;
  if (pct !== null) {
    const rounded = Math.round(pct);
    if (pct > DTC_NEGLIGIBLE_PCT) {
      cmpLabel = "Above baseline";
      cmpValue = `approximately ${Math.abs(rounded)}%`;
    } else if (pct < -DTC_NEGLIGIBLE_PCT) {
      cmpLabel = "Below baseline";
      cmpValue = `approximately ${Math.abs(rounded)}%`;
    } else {
      cmpLabel = "In line with baseline";
      cmpValue = `within ${DTC_NEGLIGIBLE_PCT}%`;
    }
  }

  // Section 2: what is happening — trajectory sentence + metrics sentence.
  const metricsSentence = (recent !== null && baseline !== null)
    ? `Recent daily demand was approximately ${dtcFmt(recent)} units per day, ` +
      `compared with a historical baseline of ${dtcFmt(baseline)} units per day.`
    : "Demand metrics for this state are incomplete, so no baseline comparison " +
      "is shown.";

  const dateLine = analysisDate
    ? `Historical analysis date: ${dtcEsc(analysisDate)}`
    : "Historical analysis date unavailable";

  return `<div class="dtc" role="group" aria-label="Demand trajectory insight">
    <div class="dtc-head">
      <span class="dtc-ico dtc-ico--${meta.tone}" aria-hidden="true">${meta.icon}</span>
      <div class="dtc-head-main">
        <div class="dtc-title">${dtcEsc(medicine)}</div>
        <div class="dtc-date${analysisDate ? "" : " dtc-na"}">${dateLine}</div>
      </div>
      <span class="dtc-badge dtc-badge--${meta.tone}">${meta.label}</span>
    </div>
    <div class="dtc-sec">
      <div class="dtc-h">What is happening?</div>
      <p class="dtc-p">Laya classifies ${dtcEsc(medicine)}'s demand as ${trajKey}.</p>
      <p class="dtc-p dtc-muted">${metricsSentence}</p>
    </div>
    <div class="dtc-sec">
      <div class="dtc-h">Supporting metrics</div>
      <div class="dtc-rows">
        <div class="dtc-row"><span>Recent demand</span><b>${recentRow}</b></div>
        <div class="dtc-row"><span>Historical baseline</span><b>${baselineRow}</b></div>
        <div class="dtc-row"><span>${cmpLabel}</span><b>${cmpValue}</b></div>
      </div>
    </div>
    <div class="dtc-sec">
      <div class="dtc-h">What does this mean?</div>
      <p class="dtc-p">${dtcMeaning(trajKey, pct)}</p>
    </div>
    <div class="dtc-foot">${DTC_DISCLAIMER}</div>
  </div>`;
}

/* Node (unit tests) export; browsers get the global function declaration. */
if (typeof module !== "undefined" && module.exports) {
  module.exports = {
    DemandTrajectoryCard,
    dtcBaselinePct,
    dtcMeaning,
    dtcInvalidCard,
    DTC_TRAJECTORIES,
    DTC_NEGLIGIBLE_PCT,
    DTC_DISCLAIMER,
  };
}
